CREATE OR REPLACE PROCEDURE dbp_macro.m_ups_ts_wbs_initiale_belieferung_standard_splits(IN P_MANDANT_ID BIGNUMERIC, 
IN P_AUSLIEFERGRUPPE_ID STRING, 
IN P_WERBE_START_WTAG_ID BIGNUMERIC,
IN P_WERBE_ENDE_WTAG_ID BIGNUMERIC,
IN P_ANZ_TAGE_WERBE_DAUER BIGNUMERIC,
IN P_INIT_LIEF_MARKT_CLUSTER_ID BIGNUMERIC,
IN P_ESTIMATION_ID BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_7_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_6_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_5_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_4_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_3_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_2_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_1_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_0_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_1_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_2_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_3_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_4_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_5_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_6_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_7_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UNTER_MHD_GRENZE_8_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
