IN P_UEBER_MHD_GRENZE_7_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_6_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_5_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_4_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_3_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_2_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_1_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_0_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_1_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_2_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_3_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_4_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_5_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_6_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_7_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_8_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_UEBER_MHD_GRENZE_9_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT BIGNUMERIC,
IN P_BBB STRING,
OUT out_param STRING)
BEGIN
BEGIN TRANSACTION;
MERGE INTO dbp_msi_data.ts_wbs_initiale_belieferung_standard_2 AS TARGET
USING (SELECT P_MANDANT_ID AS mandant_id, P_AUSLIEFERGRUPPE_ID AS ausliefergruppe_id, P_WERBE_START_WTAG_ID AS werbe_start_wtag_id, P_WERBE_ENDE_WTAG_ID AS werbe_ende_wtag_id, P_ANZ_TAGE_WERBE_DAUER AS anz_tage_werbe_dauer, P_INIT_LIEF_MARKT_CLUSTER_ID AS init_lief_markt_cluster_id, P_ESTIMATION_ID AS estimation_id, P_UNTER_MHD_GRENZE_7_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_7_tage_vor_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_6_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_6_tage_vor_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_5_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_5_tage_vor_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_4_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_4_tage_vor_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_3_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_3_tage_vor_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_2_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_2_tage_vor_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_1_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_1_tage_vor_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_0_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_0_tage_vor_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_1_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_1_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_2_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_2_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_3_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_3_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_4_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_4_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_5_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_5_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_6_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_6_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_7_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_7_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_8_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_8_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_9_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_9_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_7_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_7_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_6_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_6_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_5_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_5_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_4_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_4_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_3_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_3_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_2_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_2_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_1_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_1_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_0_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_0_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_1_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_1_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_2_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_2_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_3_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_3_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_4_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_4_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_5_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_5_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_6_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_6_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_7_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_7_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_8_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_8_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_9_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_9_tage_nach_werbestart_fix_split_prozent) AS source
ON TARGET.mandant_id = source.mandant_id 
AND TARGET.ausliefergruppe_id = source.ausliefergruppe_id 
AND TARGET.werbe_start_wtag_id = source.werbe_start_wtag_id 
AND TARGET.werbe_ende_wtag_id = source.werbe_ende_wtag_id 
AND TARGET.anz_tage_werbe_dauer = source.anz_tage_werbe_dauer 
AND TARGET.estimation_id = source.estimation_id 
AND TARGET.init_lief_markt_cluster_id = source.init_lief_markt_cluster_id
WHEN MATCHED AND P_BBB = 'UNTER' THEN UPDATE SET
    unter_mhd_grenze_7_tage_vor_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_7_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_6_tage_vor_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_6_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_5_tage_vor_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_5_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_4_tage_vor_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_4_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_3_tage_vor_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_3_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_2_tage_vor_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_2_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_1_tage_vor_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_1_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_0_tage_vor_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_0_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_1_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_1_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_2_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_2_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_3_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_3_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_4_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_4_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_5_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_5_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_6_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_6_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_7_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_7_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_8_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_8_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    unter_mhd_grenze_9_tage_nach_werbestart_fix_split_prozent = CAST(source.unter_mhd_grenze_9_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    td_update = CURRENT_TIMESTAMP()
WHEN MATCHED AND P_BBB = 'UEBER' THEN UPDATE SET
    ueber_mhd_grenze_7_tage_vor_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_7_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_6_tage_vor_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_6_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_5_tage_vor_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_5_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_4_tage_vor_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_4_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_3_tage_vor_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_3_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_2_tage_vor_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_2_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_1_tage_vor_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_1_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_0_tage_vor_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_0_tage_vor_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_1_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_1_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_2_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_2_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_3_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_3_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_4_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_4_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_5_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_5_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_6_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_6_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_7_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_7_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_8_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_8_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    ueber_mhd_grenze_9_tage_nach_werbestart_fix_split_prozent = CAST(source.ueber_mhd_grenze_9_tage_nach_werbestart_fix_split_prozent AS INTEGER),
    td_update = CURRENT_TIMESTAMP();
COMMIT TRANSACTION;
SET out_param  =  'Freeze Writeback angepasst';
SELECT out_param;
RETURN;
END;